protected void cancelClicked() {
    HighlightManager.clearHighlightsForKey(RENDER_BOX_CATEGORY);
    RenderingCache.removeBlueprint((String)"supplies");
    this.close();
}

protected void confirmClicked() {
    this.handlePlacement(BuildToolPlacementMessage.HandlerType.Survival, "minecolonies:supplies");
}

protected void handlePlacement(BuildToolPlacementMessage.HandlerType handlerType, String handlerId) {
    BlueprintPreviewData previewData = RenderingCache.getOrCreateBlueprintPreviewData((String)"supplies");
    if (structurePack == null || previewData.getBlueprint() == null) {
        return;
    }
    ArrayList<PlacementError> placementErrorList = new ArrayList<PlacementError>();
    if (type.equals("supplycamp")) {
        if (ItemSupplyCampDeployer.canCampBePlaced((Level)Minecraft.m_91087_().f_91073_, RenderingCache.getOrCreateBlueprintPreviewData((String)"supplies").getPos(), placementErrorList, (Player)Minecraft.m_91087_().f_91074_)) {
            Network.getNetwork().sendToServer((IMessage)new BuildToolPlacementMessage(handlerType, handlerId, structurePack.getName(), structurePack.getSubPath(previewData.getBlueprint().getFilePath().resolve(previewData.getBlueprint().getFileName() + ".blueprint")), previewData.getPos(), previewData.getRotation(), previewData.getMirror()));
            this.cancelClicked();
            return;
        }
    } else if (ItemSupplyChestDeployer.canShipBePlaced((Level)Minecraft.m_91087_().f_91073_, RenderingCache.getOrCreateBlueprintPreviewData((String)"supplies").getPos(), previewData.getBlueprint(), placementErrorList, (Player)Minecraft.m_91087_().f_91074_)) {
        Network.getNetwork().sendToServer((IMessage)new BuildToolPlacementMessage(handlerType, handlerId, structurePack.getName(), structurePack.getSubPath(previewData.getBlueprint().getFilePath().resolve(previewData.getBlueprint().getFileName() + ".blueprint")), previewData.getPos(), previewData.getRotation(), previewData.getMirror()));
        this.cancelClicked();
        return;
    }
    HighlightManager.clearHighlightsForKey(RENDER_BOX_CATEGORY);
    if (!placementErrorList.isEmpty()) {
        MessageUtils.format("item.supply.badblocks", new Object[0]).sendTo(new Player[]{Minecraft.m_91087_().f_91074_});
        int i = 0;
        for (PlacementError error : placementErrorList) {
            HighlightManager.addHighlight(RENDER_BOX_CATEGORY, String.valueOf(i++), new TimedBoxRenderData(error.getPos()).addText(Component.m_237115_((String)("item.supply.error." + error.getType().toString().toLowerCase())).getString()).setColor(-2130771968).setDuration(Duration.ofSeconds(60L)));
        }
    }
}

