        if (citizen.getVisibleStatus() == null) {
            statusIcon.hide();
        } else {
            statusIcon.show();
            statusIcon.setImage(citizen.getVisibleStatus().getIcon(), false);
            ((AbstractTextBuilder.TooltipBuilder)PaneBuilders.tooltipBuilder().append(Component.m_237115_((String)citizen.getVisibleStatus().getTranslationKey()))).hoverPane((Pane)statusIcon).build();
